   571     existing file moved the good copy to back->tmpfile before truncating url_sav.
   572     commit keeps the new file and drops the backup; else restore it so an aborted
   573     transfer leaves the previous copy intact. Skips the zlib .z temp. */
   574  static void back_finalize_backup(httrackp *opt, lien_back *const back,
   575                                   const hts_boolean commit) {
   576    if (back->tmpfile == NULL || back->r.compressed)
   577      return;
   578    if (commit) {
   579      (void) UNLINK(back->tmpfile); /* new copy is good; drop the backup */
   580    } else {
   581      if (back->r.out != NULL) {
   582        fclose(back->r.out);
   583        back->r.out = NULL;
   584      }
   585      /* On failure keep the backup: an orphaned temp beats losing the good copy.
   586       */
   587      if (!replace_file(back->tmpfile, back->url_sav))
   588        hts_log_print(opt, LOG_WARNING | LOG_ERRNO,
   589                      "could not restore %s; previous copy kept as %s",
   590                      back->url_sav, back->tmpfile);
   591    }
   592    back->tmpfile = NULL;
   593  }
